var d = msg.payload;
if (!d || typeof d !== 'object') {
  node.warn('Invalid sensor payload: ' + JSON.stringify(d));
  return null;
}

// Accept both raw ADC and pre-converted % values from ESP32
var temp     = parseFloat(d.temperature);
var humi     = parseFloat(d.humidity);
var soilRaw  = parseInt(d.soil_raw)   || 0;
var soilPct  = parseInt(d.soil_pct)   || Math.round((soilRaw / 4095) * 100);
var lightRaw = parseInt(d.light_raw)  || 0;
var lightPct = parseInt(d.light_pct)  || Math.round(lightRaw / 4095 * 100);

if (isNaN(temp) || isNaN(humi)) {
  node.warn('Missing temp/humi in payload');
  return null;
}

msg.payload = {
  temperature: parseFloat(temp.toFixed(1)),
  humidity:    parseFloat(humi.toFixed(1)),
  soil_raw:    soilRaw,
  soil_pct:    soilPct,
  light_raw:   lightRaw,
  light_pct:   lightPct,
  timestamp:   new Date().toISOString()
};
node.status({ fill:'green', shape:'dot',
  text: 'T:' + temp.toFixed(1) + '°C H:' + humi.toFixed(1) + '%' });
return msg;

var secret = 's85BRUupLYDqKHsYofadrGpOVpy5KfffYXk6nvNV';
msg.url     = 'https://iot-greenhouse-assignment-default-rtdb.asia-southeast1.firebasedatabase.app/sensors/current.json?auth=' + secret;
msg.method  = 'PUT';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = JSON.stringify(msg.payload);
return msg;

var d   = msg.payload;
var thr = flow.get('thresholds') || {
  temp_fan_on: 30, temp_fan_off: 25,
  soil_pump_on: 30, soil_pump_off: 70
};

var alerts = [];

if (d.temperature > thr.temp_fan_on + 5)
  alerts.push({ level:'critical', message:'Temperature critically high: ' + d.temperature + '°C' });
else if (d.temperature > thr.temp_fan_on)
  alerts.push({ level:'warning',  message:'Temperature high: ' + d.temperature + '°C' });

if (d.humidity > 85)
  alerts.push({ level:'warning',  message:'Humidity very high: ' + d.humidity + '%' });

if (d.soil_pct < thr.soil_pump_on - 10)
  alerts.push({ level:'critical', message:'Soil critically dry: ' + d.soil_pct + '%' });
else if (d.soil_pct < thr.soil_pump_on)
  alerts.push({ level:'warning',  message:'Soil moisture low: ' + d.soil_pct + '%' });

if (alerts.length === 0) return null;

var ts = Date.now();
alerts.forEach(function(a, i) { 
    // Use toLocaleString to respect the local timezone instead of forcing UTC
    a.timestamp = new Date(ts + i).toLocaleString("en-MY", { timeZone: "Asia/Kuala_Lumpur" }); 
});
msg.alerts = alerts;
return msg;

var secret = 's85BRUupLYDqKHsYofadrGpOVpy5KfffYXk6nvNV';
var base = 'https://iot-greenhouse-assignment-default-rtdb.asia-southeast1.firebasedatabase.app/alerts.json?auth=s85BRUupLYDqKHsYofadrGpOVpy5KfffYXk6nvNV' + secret;
var msgs = [];
msg.alerts.forEach(function(a) {
  msgs.push({
    url: base,
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    payload: JSON.stringify(a)
  });
});
// Send each alert as a separate message
return msgs.map(function(m) { return { payload: m.payload, url: m.url, method: m.method, headers: m.headers }; });

var d = msg.payload;
if (!d || typeof d !== 'object') {
  node.warn('Invalid actuator payload');
  return null;
}

// Normalise: accept boolean or string ON/OFF
function toState(v) {
  if (typeof v === 'boolean') return v;
  if (typeof v === 'string')  return v.toUpperCase() === 'ON';
  return !!v;
}

var now = new Date().toISOString();
msg.payload = {
  fan:       { state: toState(d.fan),       updated: now, manual: false },
  pump:      { state: toState(d.pump),      updated: now, manual: false },
  growLight: { state: toState(d.growLight), updated: now, manual: false }
};

var summary = [];
if (msg.payload.fan.state)       summary.push('Fan ON');
if (msg.payload.pump.state)      summary.push('Pump ON');
if (msg.payload.growLight.state) summary.push('Light ON');
node.status({ fill:'blue', shape:'dot',
  text: summary.length ? summary.join(', ') : 'All OFF' });
return msg;

var secret = 's85BRUupLYDqKHsYofadrGpOVpy5KfffYXk6nvNV';
msg.url     = 'https://iot-greenhouse-assignment-default-rtdb.asia-southeast1.firebasedatabase.app/actuators/status.json?auth=s85BRUupLYDqKHsYofadrGpOVpy5KfffYXk6nvNV' + secret;
msg.method  = 'PUT';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = JSON.stringify(msg.payload);
return msg;

var d = msg.payload;
if (!d || typeof d !== 'object') return null;
// Merge with existing cached thresholds
var existing = flow.get('thresholds') || {};
var merged = Object.assign({}, existing, d);
flow.set('thresholds', merged);
node.status({ fill:'green', shape:'dot', text: JSON.stringify(merged) });
// Also persist to Firebase
var secret = 's85BRUupLYDqKHsYofadrGpOVpy5KfffYXk6nvNV';
msg.url     = 'https://iot-greenhouse-assignment-default-rtdb.asia-southeast1.firebasedatabase.app/thresholds.json?auth=s85BRUupLYDqKHsYofadrGpOVpy5KfffYXk6nvNV' + secret;
msg.method  = 'PATCH';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = JSON.stringify(d);
return msg;

// Receives msg.topic = 'fan'|'pump'|'growLight', msg.payload = 'ON'|'OFF'
var device = msg.topic;
var state  = msg.payload === 'ON';
msg.payload = JSON.stringify({ [device]: state, manual: true });
msg.topic   = 'greenhouse/commands';
node.status({ fill:'orange', shape:'dot',
  text: 'CMD ' + device + ' → ' + (state ? 'ON' : 'OFF') });
return msg;

var d = msg.payload;
var defaults = { temp_fan_on:30, temp_fan_off:25, soil_pump_on:30, soil_pump_off:70 };
var merged = Object.assign({}, defaults, (d && typeof d === 'object') ? d : {});
flow.set('thresholds', merged);
node.status({ fill:'green', shape:'dot', text:'thresholds cached' });
return null;
